module land_area (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [1:0] n,\n    input wire [3:0] rect_x1,\n    input wire [3:0] rect_y1,\n    input wire [3:0] rect_x2,\n    input wire [3:0] rect_y2,\n    input wire rect_valid,\n    output reg [15:0] area,\n    output reg done\n);\n\n    localparam [2:0] IDLE      = 3'd0;\n    localparam [2:0] WAIT_RECT = 3'd1;\n    localparam [2:0] UPDATE_GRID = 3'd2;\n    localparam [2:0] COMPUTE   = 3'd3;\n    localparam [2:0] DONE_ST   = 3'd4;\n\n    reg [2:0] state;\n    reg [1:0] rect_count;\n    reg [3:0] rect_x1_reg, rect_y1_reg, rect_x2_reg, rect_y2_reg;\n    reg [3:0] x, y;\n    reg [8:0] area_acc;\n    reg [15:0] grid [0:15];\n\n    wire grid_write_en = (state == UPDATE_GRID) && (x >= rect_x1_reg) && (x < rect_x2_reg) && (y >= rect_y1_reg) && (y < rect_y2_reg);\n\n    always @(posedge clk or negedge rst_n) begin\n        integer i;\n        if (!rst_n) begin\n            state <= IDLE;\n            rect_count <= 2'd0;\n            area <= 16'd0;\n            done <= 1'd0;\n            area_acc <= 9'd0;\n            x <= 4'd0;\n            y <= 4'd0;\n\n            for (i = 0; i < 16; i = i + 1)\n                grid[i] <= 16'd0;\n\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'd0;\n                    if (start) begin\n                        for (i = 0; i < 16; i = i + 1)\n                            grid[i] <= 16'd0;\n                        rect_count <= 2'd0;\n                        state <= WAIT_RECT;\n                    end\n                end\n\n                WAIT_RECT: begin\n                    if (rect_valid) begin\n                        rect_x1_reg <= rect_x1;\n                        rect_y1_reg <= rect_y1;\n                        rect_x2_reg <= rect_x2;\n                        rect_y2_reg <= rect_y2;\n                        x <= 4'd0;\n                        y <= 4'd0;\n                        state <= UPDATE_GRID;\n                    end\n                end\n\n                UPDATE_GRID: begin\n                    if (grid_write_en) begin\n                        grid[x][y] <= 1'd1;\n                    end\n\n                    if (y == 4'd15) begin\n                        y <= 4'd0;\n                        if (x == 4'd15) begin\n                            rect_count <= rect_count + 2'd1;\n                            if (rect_count + 2'd1 == n) begin\n                                state <= COMPUTE;\n                                x <= 4'd0;\n                                y <= 4'd0;\n                            end else begin\n                                state <= WAIT_RECT;\n                            end\n                        end else begin\n                            x <= x + 4'd1;\n                        end\n                    end else begin\n                        y <= y + 4'd1;\n                    end\n                end\n\n                COMPUTE: begin\n                    if (grid[x][y]) begin\n                        area_acc <= area_acc + 9'd1;\n                    end\n\n                    if (y == 4'd15) begin\n                        y <= 4'd0;\n                        if (x == 4'd15) begin\n                            area <= {7'd0, area_acc};\n                            state <= DONE_ST;\n                        end else begin\n                            x <= x + 4'd1;\n                        end\n                    end else begin\n                        y <= y + 4'd1;\n                    end\n                end\n\n                DONE_ST: begin\n                    done <= 1'd1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule